* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #0a0a1a;
}

canvas {
  display: block;
}

// Sketch p5.js: Flor Animada
// Canvas fullscreen, pétalos con balanceo, tallo curvo, hojas y polen

let flowerX, flowerY;
let time = 0;
let pollenParticles = [];
let swayAngle = 0;

function setup() {
  createCanvas(windowWidth, windowHeight);
  flowerX = width / 2;
  flowerY = height * 0.45;

  // Inicializar partículas de polen
  for (let i = 0; i < 60; i++) {
    pollenParticles.push({
      x: random(-120, 120),
      y: random(-120, 120),
      size: random(1.5, 4),
      speed: random(0.3, 1.2),
      angle: random(TWO_PI),
      dist: random(30, 140),
      opacity: random(80, 220)
    });
  }
}

function draw() {
  // Fondo con degradado suave
  drawGradientBackground();

  time += 0.012;
  swayAngle = sin(time * 1.3) * 0.06;

  push();
  translate(flowerX, flowerY);

  // Tallo
  drawStem();

  // Hojas
  drawLeaves();

  // Pétalos (múltiples capas)
  drawPetals();

  // Centro de la flor
  drawFlowerCenter();

  // Polen flotante
  drawPollen();

  pop();
}

function drawGradientBackground() {
  // Degradado vertical de azul oscuro a verde suave
  let c1 = color(10, 12, 30);
  let c2 = color(20, 35, 25);

  for (let i = 0; i <= height; i++) {
    let inter = map(i, 0, height, 0, 1);
    let c = lerpColor(c1, c2, inter);
    stroke(c);
    line(0, i, width, i);
  }
}

function drawStem() {
  noFill();
  strokeWeight(6);

  // Tallo principal con curva bezier
  let stemBaseX = 0;
  let stemBaseY = height * 0.52;
  let cp1x = 15 + sin(time * 0.8) * 8;
  let cp1y = height * 0.25;
  let cp2x = -10 + cos(time * 0.6) * 12;
  let cp2y = height * 0.1;

  stroke(34, 139, 34);
  beginShape();
  vertex(stemBaseX, stemBaseY);
  bezierVertex(cp1x, cp1y, cp2x, cp2y, 0, 0);
  endShape();

  // Línea de textura en el tallo
  strokeWeight(1.5);
  stroke(50, 180, 50, 100);
  beginShape();
  vertex(stemBaseX + 2, stemBaseY);
  bezierVertex(cp1x + 2, cp1y, cp2x + 2, cp2y, 2, 0);
  endShape();
}

function drawLeaves() {
  noStroke();
  fill(34, 160, 34, 210);

  // Hoja izquierda
  push();
  let leafY = height * 0.28;
  let leafX = -18 + sin(time * 0.7) * 4;
  translate(leafX, leafY);
  rotate(-0.5 + swayAngle * 2);
  drawLeaf(0, 0, 50, 18);
  pop();

  // Hoja derecha
  push();
  let leafY2 = height * 0.36;
  let leafX2 = 14 + cos(time * 0.8) * 5;
  translate(leafX2, leafY2);
  rotate(0.6 - swayAngle * 2);
  drawLeaf(0, 0, 45, 15);
  pop();
}

function drawLeaf(x, y, w, h) {
  fill(40, 150, 40, 200);
  beginShape();
  vertex(x, y - h);
  bezierVertex(x + w * 0.7, y - h * 0.6, x + w * 0.8, y + h * 0.4, x, y + h);
  bezierVertex(x - w * 0.8, y + h * 0.4, x - w * 0.7, y - h * 0.6, x, y - h);
  endShape(CLOSE);

  // Nervadura
  stroke(20, 100, 20, 150);
  strokeWeight(1);
  line(x, y - h + 2, x, y + h - 4);
  noStroke();
}

function drawPetals() {
  let numPetalsOuter = 10;
  let numPetalsInner = 8;
  let numPetalsCore = 6;

  // Capa exterior - pétalos grandes
  for (let i = 0; i < numPetalsOuter; i++) {
    let angle = map(i, 0, numPetalsOuter, 0, TWO_PI);
    let petalSway = swayAngle * (1 + i * 0.15);

    push();
    rotate(angle + petalSway);
    drawPetal(0, -15, 40, 90, color(255, 105, 180, 190), color(255, 180, 200, 160));
    pop();
  }

  // Capa media - pétalos medianos
  for (let i = 0; i < numPetalsInner; i++) {
    let angle = map(i, 0, numPetalsInner, 0, TWO_PI) + PI / numPetalsInner;
    let petalSway = swayAngle * (0.8 + i * 0.2);

    push();
    rotate(angle + petalSway);
    drawPetal(0, -10, 30, 65, color(255, 140, 200, 200), color(255, 200, 220, 170));
    pop();
  }

  // Capa interior - pétalos pequeños
  for (let i = 0; i < numPetalsCore; i++) {
    let angle = map(i, 0, numPetalsCore, 0, TWO_PI);
    let petalSway = swayAngle * (0.6 + i * 0.25);

    push();
    rotate(angle + petalSway);
    drawPetal(0, -8, 20, 45, color(255, 200, 150, 210), color(255, 230, 200, 180));
    pop();
  }
}

function drawPetal(x, y, w, h, colorTop, colorBottom) {
  // Pétalo con forma de bezier
  beginShape();
  fill(colorTop);
  noStroke();

  // Base del pétalo
  vertex(x - w * 0.25, y);
  // Lado izquierdo
  bezierVertex(x - w * 0.6, y - h * 0.5, x - w * 0.5, y - h * 0.9, x, y - h);
  // Punta
  bezierVertex(x + w * 0.5, y - h * 0.9, x + w * 0.6, y - h * 0.5, x + w * 0.25, y);

  endShape(CLOSE);

  // Brillo interno
  fill(colorBottom);
  beginShape();
  vertex(x - w * 0.12, y);
  bezierVertex(x - w * 0.35, y - h * 0.4, x - w * 0.25, y - h * 0.75, x, y - h * 0.7);
  bezierVertex(x + w * 0.25, y - h * 0.75, x + w * 0.35, y - h * 0.4, x + w * 0.12, y);
  endShape(CLOSE);
}

function drawFlowerCenter() {
  // Sombra del centro
  noStroke();
  fill(200, 120, 50, 100);
  ellipse(1, 1, 32, 32);

  // Centro principal
  let centerGrad = drawingContext.createRadialGradient(0, -2, 2, 0, 0, 18);
  centerGrad.addColorStop(0, '#FFE066');
  centerGrad.addColorStop(0.5, '#FFAA33');
  centerGrad.addColorStop(1, '#CC5500');
  drawingContext.fillStyle = centerGrad;
  ellipse(0, 0, 30, 30);

  // Puntitos en el centro (estambres)
  for (let i = 0; i < 12; i++) {
    let angle = map(i, 0, 12, 0, TWO_PI);
    let sx = cos(angle) * 8;
    let sy = sin(angle) * 8;
    fill(255, 220, 100);
    ellipse(sx, sy, 4, 4);
  }

  // Punto central
  fill(255, 240, 180);
  ellipse(0, 0, 10, 10);
}

function drawPollen() {
  noStroke();
  for (let p of pollenParticles) {
    p.angle += p.speed * 0.015;
    p.dist += sin(time * 2 + p.angle) * 0.2;
    p.dist = constrain(p.dist, 20, 160);

    let px = cos(p.angle) * p.dist;
    let py = sin(p.angle) * p.dist;

    // Oscilación vertical suave
    py += sin(time * 3 + p.angle) * 15;

    let alpha = map(sin(time * 2 + p.angle), -1, 1, 60, p.opacity);
    fill(255, 220, 100, alpha);
    ellipse(px, py, p.size, p.size);

    // Brillo
    fill(255, 255, 200, alpha * 0.6);
    ellipse(px - p.size * 0.2, py - p.size * 0.2, p.size * 0.5, p.size * 0.5);
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  flowerX = width / 2;
  flowerY = height * 0.45;
}

