attribute vec2 a_position;
void main() {
    gl_Position = vec4(a_position, 0.0, 1.0);
}
`;

// --- Fragment Shader (Raymarching Torus) ---
const fragmentShaderSource = `
precision highp float;

uniform vec2 iResolution;
uniform float iTime;

#define MAX_DIST 30.0
#define HIT_THRESHOLD 0.001
#define MAX_STEPS 120

// =================================================================
// FUNCIÓN DE HASH
// =================================================================
float hash21(vec2 p) {
    p = fract(p * vec2(233.34, 851.74));
    p += dot(p, p + 23.45);
    return fract(p.x * p.y);
}

// =================================================================
// FUNCIÓN DE DISTANCIA AL SET (DE) - TORUS
// =================================================================
float de(vec3 p) {
    float R = 1.0;   // Radio mayor
    float r = 0.3;   // Radio menor

    vec2 p_xz = vec2(p.x, p.z);
    float dist_xz = length(p_xz) - R;
    float dist_sq = sqrt(dist_xz * dist_xz + p.y * p.y) - r;

    return dist_sq;   // Distancia firmada (negativa dentro, positiva fuera)
}

