// 🌸 Sketch p5.js: Flor Animada con polen, balanceo y degradado
// Canvas fullscreen | 3 capas de pétalos | Tallo curvo | Hojas | Partículas

let flowerX, flowerY;
let time = 0;
let pollenParticles = [];
let swayAngle = 0;
let bgGraphics;

function setup() {
  createCanvas(windowWidth, windowHeight);
  flowerX = width / 2;
  flowerY = height * 0.42;

  // Partículas de polen
  for (let i = 0; i < 80; i++) {
    pollenParticles.push({
      angle: random(TWO_PI),
      dist: random(15, 160),
      size: random(1.2, 4.5),
      speed: random(0.2, 0.9),
      offset: random(TWO_PI),
      opacity: random(60, 230),
      hue: random(40, 65) // amarillo/dorado
    });
  }

  bgGraphics = createGraphics(width, height);
  drawBackgroundOnce();
}

function drawBackgroundOnce() {
  // Degradado vertical nocturno
  let cTop = color(8, 10, 28);
  let cBottom = color(18, 32, 22);

  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c = lerpColor(cTop, cBottom, t);
    bgGraphics.stroke(c);
    bgGraphics.line(0, y, width, y);
  }
}

function draw() {
  // Fondo
  image(bgGraphics, 0, 0);

  // Neblina sutil animada
  drawMist();

  time += 0.01;
  swayAngle = sin(time * 1.4) * 0.07;

  push();
  translate(flowerX, flowerY);

  // Sombras bajo la flor
  drawShadow();

  // Tallo
  drawStem();

  // Hojas
  drawLeaves();

  // Pétalos (3 capas)
  drawPetals();

  // Centro de la flor
  drawFlowerCenter();

  // Polen
  drawPollen();

  pop();

  // Luciérnagas decorativas
  drawFireflies();
}

function drawMist() {
  noStroke();
  for (let i = 0; i < 3; i++) {
    let mx = width * 0.5 + sin(time * 0.3 + i * 1.5) * width * 0.4;
    let my = height * 0.6 + cos(time * 0.4 + i) * 80;
    let alpha = map(sin(time * 0.6 + i * 2), -1, 1, 3, 20);
    fill(100, 140, 120, alpha);
    ellipse(mx, my, 300 + i * 80, 180 + i * 40);
  }
}

function drawShadow() {
  noStroke();
  fill(0, 0, 0, 20);
  ellipse(0, 18, 95, 22);
}

function drawStem() {
  noFill();
  let stemBaseY = height * 0.55;

  // Puntos de control animados
  let cp1x = 12 + sin(time * 0.7) * 10;
  let cp1y = height * 0.22;
  let cp2x = -8 + cos(time * 0.55) * 14;
  let cp2y = height * 0.08;

  // Tallo grueso
  strokeWeight(7);
  stroke(28, 120, 30);
  beginShape();
  vertex(0, stemBaseY);
  bezierVertex(cp1x, cp1y, cp2x, cp2y, 0, 0);
  endShape();

  // Brillo del tallo (línea fina clara)
  strokeWeight(1.8);
  stroke(60, 170, 55, 140);
  beginShape();
  vertex(2, stemBaseY);
  bezierVertex(cp1x + 2, cp1y, cp2x + 2, cp2y, 2, 0);
  endShape();
}

function drawLeaves() {
  noStroke();

  // Hoja izquierda
  push();
  let lx1 = -16 + sin(time * 0.65) * 5;
  let ly1 = height * 0.27;
  translate(lx1, ly1);
  rotate(-0.55 + swayAngle * 2.5);
  drawLeafShape(0, 0, 52, 19, color(32, 145, 35, 220));
  pop();

  // Hoja derecha
  push();
  let lx2 = 13 + cos(time * 0.75) * 6;
  let ly2 = height * 0.34;
  translate(lx2, ly2);
  rotate(0.65 - swayAngle * 2.2);
  drawLeafShape(0, 0, 46, 16, color(38, 155, 40, 210));
  pop();

  // Hoja pequeña superior
  push();
  let lx3 = -9 + cos(time * 0.6) * 4;
  let ly3 = height * 0.15;
  translate(lx3, ly3);
  rotate(-0.3 + swayAngle * 1.8);
  drawLeafShape(0, 0, 35, 12, color(42, 160, 44, 190));
  pop();
}

function drawLeafShape(x, y, w, h, col) {
  fill(col);
  beginShape();
  vertex(x, y - h);
  bezierVertex(x + w * 0.65, y - h * 0.55, x + w * 0.75, y + h * 0.35, x, y + h);
  bezierVertex(x - w * 0.75, y + h * 0.35, x - w * 0.65, y - h * 0.55, x, y - h);
  endShape(CLOSE);

  // Nervadura central
  stroke(15, 80, 15, 160);
  strokeWeight(1.2);
  line(x, y - h + 3, x, y + h - 5);

  // Venas laterales
  let veins = 5;
  for (let v = 1; v <= veins; v++) {
    let vy = map(v, 0, veins + 1, y - h * 0.7, y + h * 0.4);
    let vw = map(abs(v - veins / 2), 0, veins / 2, w * 0.25, w * 0.08);
    stroke(20, 90, 20, 100);
    line(x - 3, vy, x - vw, vy);
    line(x + 3, vy, x + vw, vy);
  }
  noStroke();
}

function drawPetals() {
  let outerCount = 12;
  let midCount = 9;
  let innerCount = 7;

  // 🌺 Capa exterior - pétalos grandes rosados
  for (let i = 0; i < outerCount; i++) {
    let a = map(i, 0, outerCount, 0, TWO_PI);
    let sw = swayAngle * (1.1 + i * 0.12);
    push();
    rotate(a + sw);
    drawPetalShape(0, -18, 42, 95, 
      color(255, 95, 170, 195), 
      color(255, 170, 200, 155));
    pop();
  }

  // 🌷 Capa media - pétalos rosa claro
  for (let i = 0; i < midCount; i++) {
    let a = map(i, 0, midCount, 0, TWO_PI) + PI / midCount;
    let sw = swayAngle * (0.85 + i * 0.18);
    push();
    rotate(a + sw);
    drawPetalShape(0, -12, 32, 70, 
      color(255, 135, 185, 210), 
      color(255, 195, 215, 165));
    pop();
  }

  // 🌼 Capa interior - pétalos amarillos/crema
  for (let i = 0; i < innerCount; i++) {
    let a = map(i, 0, innerCount, 0, TWO_PI) + PI / (innerCount * 2);
    let sw = swayAngle * (0.55 + i * 0.22);
    push();
    rotate(a + sw);
    drawPetalShape(0, -9, 22, 50, 
      color(255, 190, 130, 220), 
      color(255, 225, 185, 175));
    pop();
  }
}

function drawPetalShape(x, y, w, h, colorOuter, colorInner) {
  // Pétalo exterior
  fill(colorOuter);
  noStroke();
  beginShape();
  vertex(x - w * 0.28, y);
  bezierVertex(x - w * 0.7, y - h * 0.45, x - w * 0.55, y - h * 0.88, x, y - h);
  bezierVertex(x + w * 0.55, y - h * 0.88, x + w * 0.7, y - h * 0.45, x + w * 0.28, y);
  endShape(CLOSE);

  // Brillo interior del pétalo
  fill(colorInner);
  beginShape();
  vertex(x - w * 0.13, y);
  bezierVertex(x - w * 0.38, y - h * 0.35, x - w * 0.28, y - h * 0.72, x, y - h * 0.68);
  bezierVertex(x + w * 0.28, y - h * 0.72, x + w * 0.38, y - h * 0.35, x + w * 0.13, y);
  endShape(CLOSE);

  // Línea central sutil
  stroke(255, 255, 255, 40);
  strokeWeight(0.7);
  line(x, y, x, y - h * 0.6);
  noStroke();
}

function drawFlowerCenter() {
  noStroke();

  // Sombra
  fill(180, 100, 40, 90);
  ellipse(1.5, 1.5, 35, 35);

  // Centro con gradiente radial
  let g = drawingContext.createRadialGradient(0, -3, 3, 0, 0, 20);
  g.addColorStop(0, '#FFE680');
  g.addColorStop(0.35, '#FFB830');
  g.addColorStop(0.7, '#E87810');
  g.addColorStop(1, '#993300');
  drawingContext.fillStyle = g;
  ellipse(0, 0, 34, 34);

  // Estambres
  for (let i = 0; i < 14; i++) {
    let a = map(i, 0, 14, 0, TWO_PI);
    let sx = cos(a) * 9.5;
    let sy = sin(a) * 9.5;
    fill(255, 225, 110);
    ellipse(sx, sy, 4.5, 4.5);
    // Puntito en cada estambre
    fill(255, 250, 200);
    ellipse(sx, sy, 1.8, 1.8);
  }

  // Anillo de puntitos
  for (let i = 0; i < 18; i++) {
    let a = map(i, 0, 18, 0, TWO_PI);
    let rx = cos(a) * 6;
    let ry = sin(a) * 6;
    fill(255, 200, 80, 200);
    ellipse(rx, ry, 2.5, 2.5);
  }

  // Brillo central
  fill(255, 245, 200, 230);
  ellipse(-1, -2, 11, 11);
  fill(255, 255, 240, 180);
  ellipse(-1.5, -2.5, 6, 6);
}

function drawPollen() {
  noStroke();
  for (let p of pollenParticles) {
    p.angle += p.speed * 0.012;
    p.dist += sin(time * 2.3 + p.offset) * 0.25;
    p.dist = constrain(p.dist, 12, 170);

    let px = cos(p.angle) * p.dist;
    let py = sin(p.angle) * p.dist;
    py += sin(time * 2.8 + p.offset) * 18;

    let alpha = map(sin(time * 2.5 + p.offset), -1, 1, 40, p.opacity);
    let sz = p.size * map(sin(time * 1.8 + p.offset), -1, 1, 0.7, 1.3);

    // Halo suave
    fill(255, 230, 120, alpha * 0.3);
    ellipse(px, py, sz * 2.5, sz * 2.5);

    // Partícula principal
    fill(255, 215, 80, alpha);
    ellipse(px, py, sz, sz);

    // Brillo
    fill(255, 250, 200, alpha * 0.7);
    ellipse(px - sz * 0.25, py - sz * 0.25, sz * 0.5, sz * 0.5);
  }
}

function drawFireflies() {
  noStroke();
  let ffCount = 5;
  for (let i = 0; i < ffCount; i++) {
    let fx = width * (0.15 + (i * 0.18)) + sin(time * 0.7 + i * 2.3) * width * 0.12;
    let fy = height * (0.2 + i * 0.12) + cos(time * 0.9 + i * 1.8) * height * 0.15;
    let pulse = pow(abs(sin(time * 2 + i * 1.5)), 3);
    let alpha = pulse * 180;
    let sz = 3 + pulse * 6;

    fill(180, 255, 120, alpha * 0.4);
    ellipse(fx, fy, sz * 3, sz * 3);
    fill(220, 255, 180, alpha * 0.7);
    ellipse(fx, fy, sz, sz);
    fill(255, 255, 240, alpha);
    ellipse(fx - sz * 0.2, fy - sz * 0.2, sz * 0.35, sz * 0.35);
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  flowerX = width / 2;
  flowerY = height * 0.42;

  // Regenerar fondo
  bgGraphics = createGraphics(width, height);
  let cTop = color(8, 10, 28);
  let cBottom = color(18, 32, 22);
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c = lerpColor(cTop, cBottom, t);
    bgGraphics.stroke(c);
    bgGraphics.line(0, y, width, y);
  }
}
